import cats.effect.IO
import io.circe.literal._
import grackle._
import grackle.circe.CirceMapping
import grackle.syntax._

object TestCirceMapping extends CirceMapping[IO] {
  val schema =
    schema"""
      type Query { root: Root }
      type Root {
        bool: Boolean
        int: Int
        string: String
        array: [Int!]
        object: A
      }
      type A { id: ID, aField: Int }
    """

  val QueryType = schema.ref("Query")

  val data =
    json"""
      {
        "bool": true,
        "int": 23,
        "string": "foo",
        "array": [1, 2, 3],
        "object": { "id": "obj", "aField": 27 }
      }
    """

  val typeMappings =
    List(
      ObjectMapping(
        tpe = QueryType,
        fieldMappings = List(
          CirceField("root", data)
        )
      )
    )
}

// run a query
TestCirceMapping.compileAndRun("""query { root { int string object { aField } } }""")

import cats.data.OptionT
import io.circe.Json
import grackle._
import grackle.syntax._

// inside a CirceMapping with `data` containing a top-level "hidden": 13
val BigDecimalType = schema.ref("BigDecimal")
val RootType = schema.ref("Root")

val typeMappings =
  List(
    ObjectMapping(
      tpe = RootType,
      fieldMappings = List(
        CursorField("computed", computeField, List("hidden"))
      )
    ),
    LeafMapping[BigDecimal](BigDecimalType)
  )

def computeField(c: Cursor): Result[Option[Int]] =
  (for {
    n <- OptionT(c.fieldAs[Json]("hidden").map(_.asNumber))
    i <- OptionT(Result(n.toInt))
  } yield i + 1).value

import cats.effect.Sync
import cats.implicits._
import io.circe.{Encoder, Json}
import grackle._
import grackle.circe.CirceMapping
import grackle.syntax._

class TestCirceEffectMapping[F[_]: Sync] extends CirceMapping[F] {
  val schema = schema"""
    type Query { foo: Struct!, bar: Struct!, baz: Struct! }
    type Struct { n: Int!, s: String! }
  """
  val QueryType = schema.ref("Query")

  case class Struct(n: Int, s: String)
  implicit val EncodeStruct: Encoder[Struct] = s =>
    Json.obj("n" -> Json.fromInt(s.n), "s" -> Json.fromString(s.s))

  val typeMappings = List(
    ObjectMapping(
      tpe = QueryType,
      fieldMappings = List(
        // full control: build the CirceCursor yourself
        RootEffect.computeCursor("foo")((p, e) =>
          Sync[F].pure(Result(circeCursor(p, e,
            Json.obj("n" -> Json.fromInt(42), "s" -> Json.fromString("hi")))))),
        // yield Json, let circe build the cursor
        RootEffect.computeJson("bar")((_, _) =>
          Sync[F].pure(Result(Json.obj("n" -> Json.fromInt(42), "s" -> Json.fromString("ho"))))),
        // yield an encodable value
        RootEffect.computeEncodable("baz")((_, _) =>
          Sync[F].pure(Result(Struct(44, "hee"))))
      )
    )
  )
}

import cats.effect.IO
import io.circe.Json
import io.circe.literal._
import grackle.circe.CirceMapping
import grackle.syntax._

object CircePriorityMapping extends CirceMapping[IO] {
  val schema = schema"""
    scalar Foo
    type Monkey { name: Foo }
    type Barrel { monkey: Monkey }
    type Query { present: Barrel, fallback: Barrel }
  """
  val QueryType  = schema.ref("Query")
  val MonkeyType = schema.ref("Monkey")
  val FooType    = schema.ref("Foo")

  val typeMappings = List(
    ObjectMapping(QueryType, List(
      CirceField("present",  json"""{ "monkey": { "name": "Bob" }}"""),
      CirceField("fallback", json"""{ "monkey": {}}""")
    )),
    ObjectMapping(MonkeyType, List(
      CirceField("name", Json.fromString("Steve"))
    )),
    LeafMapping[String](FooType)
  )
}
// present.monkey.name == "Bob" (from JSON); fallback.monkey.name == "Steve" (explicit mapping)
